import {useCallback,useEffect,useRef,useState} from 'react';
import {Activity,ArrowDownLeft,ArrowDownRight,ArrowRight,ArrowUpRight,BarChart3,Bell,Bitcoin,BookOpen,Check,CheckCircle2,ChevronDown,ChevronRight,Clock3,Copy,Database,Download,ExternalLink,FlaskConical,Globe2,LayoutDashboard,Link2,LoaderCircle,LockKeyhole,Maximize2,MessageSquare,Minus,MoreHorizontal,Newspaper,Pause,Play,Plus,Power,RefreshCw,Search,Settings2,Shield,ShieldCheck,SlidersHorizontal,Sparkles,TrendingUp,TriangleAlert,Wallet,X,Zap} from 'lucide-react';
import {PriceChart,EquityChart} from './Chart';
import {PaperSession} from './PaperSession';
import {ExecutionStatus} from './ExecutionStatus';
import {UniversePanel} from './UniversePanel';
import {PortfolioControls} from './PortfolioControls';
import './paper.css';
import './simple.css';
import {HistorySummary} from './HistorySummary';
import {ResearchLibrary} from './ResearchLibrary';
import {ChatPanel} from './ChatPanel';
import {OperationsPanel} from './OperationsPanel';
import type {Candle,Row,Snapshot} from './types';

const nav=[{id:'overview',label:'Genel bakış',icon:LayoutDashboard},{id:'chat',label:'AI sohbet',icon:MessageSquare},{id:'operations',label:'İşlem merkezi',icon:ShieldCheck},{id:'markets',label:'Piyasalar',icon:BarChart3},{id:'trades',label:'İşlemler',icon:ArrowDownLeft},{id:'strategies',label:'Stratejiler',icon:Sparkles},{id:'lab',label:'Test laboratuvarı',icon:FlaskConical},{id:'news',label:'Haber merkezi',icon:Newspaper},{id:'exchanges',label:'Borsalar',icon:Link2},{id:'settings',label:'Ayarlar',icon:Settings2}];
const n=(v:number,d=2)=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:d,maximumFractionDigits:d}).format(Number.isFinite(v)?v:0);
const priceDigits=(v:number)=>v<0.01?8:v<1?6:v<10?4:2;
const signed=(v:number,d=2)=>(v>=0?'+':'−')+n(Math.abs(v),d);
const when=(v:number)=>new Date(v*1000).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const methodName=(id:string)=>({manual:'Kullanıcı talimatı',breakout:'Kırılım',momentum:'Momentum',pullback:'Geri çekilme',reversion:'Ortalamaya dönüş',squeeze:'Sıkışma'} as Row)[id]||'';
const strategyName=(id:string)=>id==='intraday'?'Gün içi · 15dk':id==='swing'?'Swing · 4s':id;
const assetName=(symbol:string)=>({BTC:'Bitcoin',ETH:'Ethereum',SOL:'Solana',BNB:'BNB',XRP:'XRP',DOGE:'Dogecoin',ADA:'Cardano',AVAX:'Avalanche',LINK:'Chainlink',DOT:'Polkadot',LTC:'Litecoin',BCH:'Bitcoin Cash',TRX:'TRON',SUI:'Sui',ICP:'Internet Computer',NEAR:'NEAR',APT:'Aptos',ARB:'Arbitrum',OP:'Optimism',ATOM:'Cosmos',UNI:'Uniswap',AAVE:'Aave',FIL:'Filecoin',INJ:'Injective'} as Row)[symbol.replace('USDT','')]||symbol.replace('USDT','');
function Coin({symbol,small=false}:{symbol:string;small?:boolean}){const base=symbol.replace('USDT','');const hue=[...base].reduce((a,c)=>a+c.charCodeAt(0)*7,0)%360;return <span style={base!=='BTC'&&base!=='ETH'?{color:`hsl(${hue} 75% 72%)`,background:`hsl(${hue} 30% 20%)`}:undefined} className={'coin '+(base==='BTC'?'btc':base==='ETH'?'eth':'alt')+(small?' small':'')}>{base==='BTC'?<Bitcoin size={small?15:20}/>:base==='ETH'?<span className="eth-glyph">◆</span>:base.slice(0,2)}</span>}
function Badge({children,tone='neutral'}:{children:React.ReactNode;tone?:string}){return <span className={'badge '+tone}>{children}</span>}
function Empty({title,text,icon:Icon=Database}:{title:string;text:string;icon?:any}){return <div className="empty"><span className="empty-icon"><Icon size={25}/></span><strong>{title}</strong><p>{text}</p></div>}
function SectionHead({title,meta,action}:{title:string;meta?:string;action?:React.ReactNode}){return <div className="section-head"><div><h3>{title}</h3>{meta&&<span>{meta}</span>}</div>{action}</div>}

export default function App(){
  const [page,setPage]=useState('overview');
  const [presentation,setPresentation]=useState<'simple'|'pro'>(()=>{try{return localStorage.getItem('kripto.presentation')==='pro'?'pro':'simple';}catch{return 'simple';}});
  const [chartRange,setChartRange]=useState<'near'|'6'|'12'>('near');
  const [historyInterval,setHistoryInterval]=useState('1d');
  const [history,setHistory]=useState<Row|null>(null);
  const [historyRetry,setHistoryRetry]=useState(0);
  const simple=presentation==='simple';
  const changePresentation=(value:'simple'|'pro')=>{setPresentation(value);try{localStorage.setItem('kripto.presentation',value);}catch{}};
  const [data,setData]=useState<Snapshot|null>(null);
  const [error,setError]=useState('');
  const [toast,setToast]=useState<{text:string;ok:boolean}|null>(null);
  const [busy,setBusy]=useState(false);
  const [symbol,setSymbol]=useState('BTCUSDT');
  const [venue,setVenue]=useState('Binance');
  const [market,setMarket]=useState('spot');
  const [interval,setIntervalValue]=useState('15m');
  const [rows,setRows]=useState<Candle[]>([]);
  const [focusedQuote,setFocusedQuote]=useState<Row|null>(null);
  const [chartLoading,setChartLoading]=useState(true);
  const [chartError,setChartError]=useState('');
  const [indicators,setIndicators]=useState(true);
  const [search,setSearch]=useState('');
  const [tradeTab,setTradeTab]=useState('open');
  const [strategyFilter,setStrategyFilter]=useState('all');
  const [settings,setSettings]=useState<Row|null>(null);
  const [credential,setCredential]=useState({venue:'Binance',key:'',secret:'',testnet:false});
  const [secret,setSecret]=useState({telegram:'',ai:''});
  const [lab,setLab]=useState({strategy:'intraday',symbol:'BTCUSDT',venue:'Binance',market:'spot',source:'DEMO',months:36,fee_bps:10,slippage_bps:3});
  const [selectedReport,setSelectedReport]=useState<Row|null>(null);
  const [proposal,setProposal]=useState<Row|null>(null);
  const [prompt,setPrompt]=useState('');
  const [confirmation,setConfirmation]=useState<{title:string;text:string;run:()=>void}|null>(null);
  const alive=useRef(true);
  const bootTime=useRef(Date.now());
  const hadData=useRef(false);
  const notify=useCallback((text:string,ok=true)=>setToast({text,ok}),[]);
  const refresh=useCallback(async()=>{
    try{
      if(!window.terminal){setError('Masaüstü bağlantısı bulunamadı. Uygulamayı EXE üzerinden açın.');return;}
      const ready=await window.terminal.ready();
      if(!ready.ready){if(hadData.current||Date.now()-bootTime.current>20000)setError('İşlem motoruna erişilemiyor. Uygulamayı tamamen kapatıp yeniden açın.');return;}
      const next=await window.terminal.request<Snapshot>('/snapshot');
      if(alive.current){hadData.current=true;setData(next);setError('');setSettings(old=>old||next.settings);}
    }catch(e){if(alive.current)setError('İşlem motoruyla bağlantı kurulamadı. Pencereyi açıp kapatmak motoru yeniden başlatmaz.');}
  },[]);
  useEffect(()=>{alive.current=true;refresh();const id=window.setInterval(refresh,1800);return()=>{alive.current=false;clearInterval(id);};},[refresh]);
  useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(null),5500);return()=>clearTimeout(id);},[toast]);
  const mode=data?.mode;
  const entryGate=data?.execution?.entry_gate;
  const engineLabel=entryGate?.blocked?entryGate.label:data?.running?'Motor çalışıyor':data?'Motor hazır':'Motor başlıyor';
  useEffect(()=>{if(data?.settings.allowlist.length&&!data.settings.allowlist.includes(symbol))setSymbol(data.settings.allowlist[0]);},[data?.settings.allowlist,symbol]);
  useEffect(()=>{
    if(!data||mode!=='PAPER'){setFocusedQuote(null);return;}
    let cancelled=false;let timer:number|undefined;
    async function poll(){
      try{
        const result=await window.terminal.request('/quote?'+new URLSearchParams({symbol,venue,market}));
        if(!cancelled)setFocusedQuote(result.mode==='PAPER'?result.quote:null);
      }catch{if(!cancelled)setFocusedQuote(null);}
      finally{if(!cancelled)timer=window.setTimeout(poll,400);}
    }
    poll();return()=>{cancelled=true;window.clearTimeout(timer);};
  },[symbol,venue,market,mode,!!data]);
  const candleBucket=chartRange==='near'?Math.floor((data?.timestamp||0)/60):0;
  const effectiveHistoryInterval=simple?'1d':historyInterval;
  useEffect(()=>{
    if(!data)return;
    let cancelled=false;setChartLoading(true);setChartError('');setHistory(null);
    const route=chartRange==='near'?'/candles?'+new URLSearchParams({symbol,interval,venue,market}):'/history?'+new URLSearchParams({symbol,venue,market,months:chartRange,interval:effectiveHistoryInterval});
    window.terminal.request(route).then(result=>{
      if(cancelled)return;setRows(result.rows||[]);setHistory(chartRange==='near'?null:result);setChartError(result.error||'');setChartLoading(false);
    }).catch(()=>{if(!cancelled){setRows([]);setChartLoading(false);setChartError('Grafik verisi alınamadı. Borsa bağlantısını kontrol edip yeniden deneyin.');}});
    return()=>{cancelled=true;};
  },[symbol,interval,venue,market,mode,!!data,candleBucket,chartRange,effectiveHistoryInterval,historyRetry]);
  async function call(route:string,body?:unknown){
    setBusy(true);
    try{const result=await window.terminal.request(route,'POST',body);notify(result.message||'Tamamlandı.',result.ok!==false);if(result.ok!==false&&(route==='/settings'||(route==='/command'&&(body as Row)?.kind==='risk_profile')))setSettings(null);await refresh();return result;}
    catch(e){notify(e instanceof Error?e.message:'İşlem tamamlanamadı.',false);return null;}
    finally{setBusy(false);}
  }
  const command=(kind:string,payload:Row={})=>call('/command',{kind,payload});
  const confirm=(title:string,text:string,run:()=>void)=>setConfirmation({title,text,run});
  const navigate=(id:string)=>{setPage(id);setSelectedReport(null);};
  const selectCoin=(s:string)=>{setSymbol(s);navigate('markets');};
  const snapshotQuote=data?.markets.find(q=>q.symbol===symbol&&q.venue===venue&&q.market===market);
  const matchesQuote=focusedQuote?.symbol===symbol&&focusedQuote?.venue===venue&&focusedQuote?.market===market;
  const activeQuote=mode==='PAPER'&&matchesQuote&&(focusedQuote?.price_observed||0)>=(snapshotQuote?.price_observed||0)?focusedQuote:snapshotQuote;
  const priceAge=activeQuote?Math.max(0,Date.now()/1000-(activeQuote.price_observed||activeQuote.observed)):0;
  const chartPositions=(data?.positions||[]).filter(p=>p.symbol===symbol&&p.venue===venue&&p.market===market);
  const chartPositionKey=JSON.stringify(chartPositions.map(p=>({id:p.id,stop:p.stop,target:p.target,side:p.side,liquidation_price:p.liquidation_price})));
  const stableChartPositions=useRef<Row[]>([]);
  const lastPositionKey=useRef('');
  if(lastPositionKey.current!==chartPositionKey){lastPositionKey.current=chartPositionKey;stableChartPositions.current=chartPositions;}

  function positionTable(items:Row[],closed=false){
    return items.length?<div className="table-scroll"><table><thead><tr><th>Varlık / piyasa</th><th>Strateji</th><th>Yön</th><th className="num">Miktar</th><th className="num">Giriş</th><th className="num">{closed?'Net sonuç':'Kapatılırsa net ≈'}</th><th/></tr></thead><tbody>{items.map(p=><tr key={p.id}><td><div className="asset-cell"><Coin symbol={p.symbol} small/><div><strong>{p.symbol.replace('USDT','')}<span className="muted"> / USDT</span></strong><small>{p.venue} · {p.market==='spot'?'Spot':'Vadeli'}{p.sample?' · Demo':''}</small></div></div></td><td><span className="cell-secondary">{strategyName(p.strategy)}{p.method&&<small>{methodName(p.method)} · {({safe:'Korumacı',balanced:'Dengeli',aggressive:'Atak',mixed:'Karma',custom:'Özel'} as Row)[p.risk_style]||'Standart'} · ×{n(p.risk_multiplier||1,2)}</small>}</span></td><td><Badge tone={p.side==='long'?'positive':'negative'}>{p.side.toUpperCase()}</Badge></td><td className="num">{n(p.quantity,5)}{!closed&&p.exit_status&&<small className="position-exit-note">{p.exit_status}{p.partial_realized?` · Kısmi net ${signed(p.partial_realized)} USDT`:''}</small>}</td><td className="num">{n(p.entry,priceDigits(p.entry))}{!closed&&p.market==='futures'&&<small title="Muhafazakâr sanal model; borsanın kesin tasfiye fiyatı değildir.">Tasfiye ≈ {n(p.liquidation_price,priceDigits(p.liquidation_price))}<br/>{p.mark_fresh?'İşaret fiyatı güncel':'İşaret fiyatı bekleniyor'}</small>}</td><td className={'num '+((closed?p.net:p.net_if_close)>=0?'positive-text':'negative-text')}>{signed(closed?p.net:p.net_if_close)}<small>USDT</small></td><td>{closed?<span className="muted text-xs">{p.reason}</span>:<button className="button subtle small-button" onClick={()=>confirm('Sanal pozisyonu kapat','Güncel fiyatla sanal çıkış ve tahmini komisyon kaydedilecek.',()=>command('close',{id:p.id}))}>Kapat</button>}</td></tr>)}</tbody></table></div>:<Empty title={closed?'Henüz kapanmış işlem yok':'Açık pozisyon bulunmuyor'} text={closed?'Kapanan işlemler ve maliyet dökümleri burada görünecek.':'Sinyal geldiğinde risk kontrolünü geçen sanal işlemler burada görünecek.'} icon={Activity}/>;
  }

  function chartCard(expanded=false){return <div className={'panel chart-panel '+(expanded?'expanded':'')}>
    <div className="chart-header"><div className="asset-title"><Coin symbol={symbol}/><div><strong>{symbol.replace('USDT','')}<span>/ USDT</span><ChevronDown size={13}/></strong><small>{assetName(symbol)} <span>· {venue} {market==='spot'?'Spot':'Vadeli'}</span></small></div></div>
      <div className="chart-price">{activeQuote?<><strong>{n(activeQuote.price,priceDigits(activeQuote.price))}</strong><span className={activeQuote.change>=0?'positive-text':'negative-text'}>{signed(activeQuote.change)}% <small>24s</small></span><small data-testid="price-freshness" className={priceAge>5?'negative-text':'muted'}>{mode==='DEMO'?'Örnek fiyat':`Son işlem · ${activeQuote.price_transport==='websocket'?'WebSocket':'Yedek REST'} · ${n(priceAge,1)} sn önce`}</small></>:<span className="muted">Veri bekleniyor</span>}</div>
      <div className="chart-selectors"><select aria-label="Grafik borsası" value={venue} onChange={e=>setVenue(e.target.value)}><option>Binance</option><option>Bybit</option></select><select aria-label="Grafik piyasası" value={market} onChange={e=>setMarket(e.target.value)}><option value="spot">Spot</option><option value="futures">Vadeli</option></select></div>
    </div>
    <div className="chart-range-bar"><span>Grafik dönemi</span><div className="segmented" role="group" aria-label="Grafik dönemi">{[['near','Yakın'],['6','6 ay'],['12','1 yıl']].map(([value,label])=><button key={value} aria-pressed={chartRange===value} className={chartRange===value?'selected':''} onClick={()=>setChartRange(value as 'near'|'6'|'12')}>{label}</button>)}</div>{chartRange!=='near'&&<><span className="range-granularity">{effectiveHistoryInterval==='1d'?'Günlük mumlar':'4 saatlik mumlar'}</span><button className="text-button" aria-label="Grafik geçmişini yenile" disabled={chartLoading} onClick={()=>setHistoryRetry(v=>v+1)}><RefreshCw size={12}/>Yenile</button></>}</div>
    <div className="chart-toolbar"><div className="segmented" role="group" aria-label="Mum zaman aralığı">{(chartRange==='near'?['15m','1h','4h','1d']:simple?['1d']:['4h','1d']).map(tf=><button key={tf} className={(chartRange==='near'?interval:effectiveHistoryInterval)===tf?'selected':''} onClick={()=>chartRange==='near'?setIntervalValue(tf):setHistoryInterval(tf)}>{({'15m':'15dk','1h':'1s','4h':'4s','1d':'1g'} as Row)[tf]}</button>)}</div><button className={'text-button indicator-button '+(indicators?'active':'')} onClick={()=>setIndicators(!indicators)}><SlidersHorizontal size={13}/> Göstergeler</button><span className="chart-legend"><i className="gold"/>EMA 20 <i className="blue"/>EMA 50</span><button className="icon-button chart-expand" title="Piyasalar ekranı" onClick={()=>navigate('markets')}><Maximize2 size={14}/></button></div>
    <div className="chart-body">{chartLoading?<div className="chart-overlay"><LoaderCircle className="spin"/>Grafik hazırlanıyor</div>:!rows.length?<Empty title={chartError?"Grafik bağlantısı bekleniyor":"Bu dönem için mum bulunamadı"} text={chartError||"Seçilen piyasanın tarihsel verisi henüz mevcut değil."}/>:<PriceChart rows={rows} positions={stableChartPositions.current} indicators={indicators}/>}</div>
    {chartRange!=='near'&&history&&<HistorySummary history={history} error={chartError} detailed={!simple}/>}
    <div className="chart-footer"><span><span className="status-dot"/>{mode==='DEMO'?'SENTETİK DEMO VERİSİ':chartRange==='near'?'KAPANMIŞ MUMLAR · FİYAT ANLIK':'GERÇEK GEÇMİŞ · YALNIZ KAPANMIŞ MUMLAR'}</span><span>UTC+3 · İstanbul</span></div>
  </div>}

  function overview(){if(!data)return null;const m=data.metrics;return <>
    <div className="page-heading"><div><div className="eyebrow">PORTFÖY ÇALIŞMA ALANI</div><h1>Piyasaya bir adım yukarıdan bak.</h1><p>Gerçek veride sanal portföy, otomatik stratejiler ve görünür kararlar.</p></div><Badge tone="blue">Gerçek para kullanılmaz</Badge></div>
    <div className="stats-grid">
      <div className="stat-card"><div className="stat-label">Toplam özsermaye <Wallet size={15}/></div><div className="stat-value">{n(m.equity)}<small>USDT</small></div><div className="stat-foot"><span className={m.net>=0?'positive-text':'negative-text'}><ArrowUpRight size={13}/>{signed(m.net_pct)}%</span><span>başlangıçtan bu yana</span></div>{mode==='DEMO'&&<div className="mini-bars">{[22,30,24,37,32,43,38,49,43,57,53,64,56,73,68,79,76,91].map((h,i)=><i key={i} style={{height:h+'%'}}/>)}</div>}</div>
      <div className="stat-card"><div className="stat-label">Maliyet sonrası sonuç <TrendingUp size={15}/></div><div className={'stat-value '+(m.net>=0?'positive-text':'negative-text')}>{signed(m.net)}<small>USDT</small></div><div className="stat-foot"><span className="muted">{n(m.fees)} USDT komisyon dahil</span></div><span className="stat-decoration">NET</span></div>
      <div className="stat-card"><div className="stat-label">Açık portföy riski <Shield size={15}/></div><div className="stat-value">%{n(m.risk_pct)}<small>/ %{n(data.settings.total_risk,0)}</small></div><div className="risk-track"><i style={{width:Math.min(100,m.risk_pct/data.settings.total_risk*100)+'%'}}/></div><div className="stat-foot"><span className="positive-text"><ShieldCheck size={13}/> {m.risk_pct<=data.settings.total_risk?'Sınırlar içinde':'Risk sınırı aşıldı'}</span></div></div>
      <div className="stat-card"><div className="stat-label">Hesap düşüşü <ArrowDownRight size={15}/></div><div className="stat-value">%{n(m.drawdown)}<small>/ %{n(data.settings.drawdown,0)}</small></div><div className="stat-foot"><span className="muted">{data.positions.length} açık pozisyon</span><span className="tiny-divider"/><span className="muted">{m.closed_count} kapanan</span></div></div>
    </div>
    <UniversePanel data={data} compact busy={busy} onRefresh={()=>call('/universe-refresh')} onBrowse={()=>navigate('markets')}/>
    <PortfolioControls data={data} busy={busy} choose={profile=>command('risk_profile',{profile})}/>
    <PaperSession data={data} busy={busy} start={balance=>{if(data.mode==='PAPER'&&data.session?.started_at)confirm('Yeni sanal oturum','Mevcut sonuçlar yerel arşive alınacak ve seçtiğin bakiyeyle yeni oturum başlayacak.',()=>command('paper_session',{balance}));else command('paper_session',{balance});}} resume={()=>command('start')}/>
    <div className="dashboard-grid"><div className="main-column">{chartCard()}<div className="panel positions-panel"><SectionHead title="Pozisyonlar" meta="Birleşik portföy · tüm borsalar" action={<button className="text-button" onClick={()=>navigate('trades')}>Tüm işlemler <ArrowRight size={13}/></button>}/>{positionTable(data.positions)}</div></div>
    <aside className="right-column"><div className="panel watchlist"><SectionHead title="Piyasa radarı" action={<button className="icon-button" title="İzin listesini düzenle" onClick={()=>navigate('settings')}><Plus size={16}/></button>}/>{data.settings.allowlist.slice(0,6).map((s:string)=>{const q=data.markets.find(q=>q.symbol===s&&q.venue==='Binance'&&q.market==='spot');return <button key={s} className={'watch-row '+(symbol===s?'active':'')} onClick={()=>setSymbol(s)}><Coin symbol={s}/><div><strong>{s.replace('USDT','')}</strong><small>{assetName(s)}</small></div><div className="watch-price"><strong>{q?n(q.price,priceDigits(q.price)):'—'}</strong><small className={q?.change>=0?'positive-text':'negative-text'}>{q?signed(q.change)+'%':'Bağlantı bekliyor'}</small></div>{mode==='DEMO'&&<svg className={'sparkline '+(q?.change>=0?'up':'down')} viewBox="0 0 60 28"><path d={s.startsWith('BTC')?'M1 24L7 18L13 21L20 10L25 15L31 8L37 13L44 4L50 8L59 1':'M1 4L8 9L14 6L21 16L27 11L34 18L41 14L49 24L55 19L59 26'}/></svg>}</button>})}<button className="watch-footer" onClick={()=>navigate('markets')}>Piyasaları keşfet <ArrowRight size={13}/></button></div>
    <div className="panel equity-panel"><SectionHead title="Özsermaye eğrisi" meta={mode==='DEMO'?'Örnek hesap geçmişi':'Sanal hesap geçmişi'} action={<Badge tone="positive">{signed(m.net_pct)}%</Badge>}/><strong className="equity-total">{n(m.equity)} <small>USDT</small></strong><EquityChart points={data.curve}/><div className="equity-labels"><span>Grafik başlangıcı</span><span>Şimdi</span></div></div>
    <div className="panel events-panel"><SectionHead title="Gündem & olaylar" action={<button className="icon-button" title="Haber merkezi" onClick={()=>navigate('news')}><ArrowUpRight size={16}/></button>}/>{data.news.slice(0,3).map((event,i)=><div className="event-row" key={event.id}><span className={'event-icon '+(i===0?'amber':'')}><Globe2 size={14}/></span><div><span className="event-source">{event.source}</span><strong>{event.title}</strong><small>{event.demo?'Örnek olay · işlem kısıtı yok':event.verification==='official'?'Resmî kaynak':'Doğrulama bekliyor'}</small></div></div>)}{!data.news.length&&<p className="inline-empty">Kaynaklardan olay bekleniyor.</p>}<div className="event-note"><ShieldCheck size={13}/> Haberler risk katmanından geçer.</div></div>
    </aside></div>
    <div className="panel system-strip"><div><span className="system-orb"><Activity size={17}/></span><div><strong>{entryGate?.blocked?entryGate.label:data.running?'Sanal motor çalışıyor':'İşlem motoru hazır'}</strong><small>{entryGate?.blocked?entryGate.message:data.running?'Yeni sinyaller ortak risk kontrolünden geçiyor.':'Yeni girişler duraklatıldı. Hazır olduğunda başlat.'}</small></div></div><div className="system-tags"><span><i className="status-dot"/>SQLite kayıtları</span><span><ShieldCheck size={13}/>Canlı emir kilidi</span><span><Clock3 size={13}/>İstanbul / UTC+3</span></div></div>
  </>}

  function simpleOverview(){if(!data)return null;const m=data.metrics;const active=mode==='PAPER'&&!!data.session?.started_at;const reasons=(data.decisions||[]).slice().sort((a,b)=>b.observed-a.observed).slice(0,3);return <>
    <div className="page-heading simple-heading"><div><div className="eyebrow">SENİN ÇALIŞMA ALANIN</div><h1>Portföyün bir bakışta.</h1><p>{mode==='DEMO'?'Örnek verileri inceliyorsun.':'Gerçek piyasayı izle, sanal işlemlerini takip et.'}</p></div><Badge tone="blue">Gerçek para kullanılmaz</Badge></div>
    <div className="simple-stats" data-testid="simple-stats"><div><span>Toplam bakiye</span><strong data-testid="account-equity">{n(m.equity)} <small>USDT</small></strong></div><div><span>Maliyet sonrası net sonuç</span><strong className={m.net>=0?'positive-text':'negative-text'}>{signed(m.net)} <small>USDT</small></strong></div><div><span>Açık pozisyonlar</span><strong>{data.positions.length} <small>/ {data.settings.max_positions} sınır</small></strong></div></div>
    <div className="simple-status panel"><div><span className="status-dot"/><strong>{entryGate?.blocked?entryGate.label:data.running?'Bot piyasayı izliyor':'Yeni girişler duraklatıldı'}</strong><small>{data.settings.allowlist.length} coin · açık risk %{n(m.risk_pct)} / %{n(data.settings.total_risk)} · hesap düşüşü %{n(m.drawdown)}</small></div><label>İşlem tarzı<select aria-label="Sade işlem tarzı" disabled={busy} value={data.settings.risk_profile} onChange={e=>command('risk_profile',{profile:e.target.value})}>{Object.entries(data.risk_profiles||{}).map(([id,p])=><option key={id} value={id}>{p.name}</option>)}{data.settings.risk_profile==='custom'&&<option value="custom">Özel</option>}</select></label><button className="text-button" onClick={()=>navigate('settings')}>Risk ayarları <ArrowRight size={13}/></button></div>
    {mode==='DEMO'?<div className="notice"><FlaskConical size={16}/><span>Örnek fiyatlar ve işlemler gösteriliyor. Güncel piyasa verileri için sanal hesaba geç.</span><button className="text-button" disabled={busy} onClick={()=>command('mode',{mode:'PAPER'})}>Sanal hesaba geç <ArrowRight size={13}/></button></div>:!active?<PaperSession data={data} busy={busy} start={balance=>command('paper_session',{balance})} resume={()=>command('start')}/>:<details className="simple-details"><summary>Oturum, AI ve öğrenme ayrıntıları</summary><PaperSession data={data} busy={busy} start={balance=>confirm('Yeni sanal oturum','Mevcut sonuçlar arşivlenecek ve seçilen bakiye ile yeni oturum başlayacak.',()=>command('paper_session',{balance}))} resume={()=>command('start')}/><PortfolioControls data={data} busy={busy} choose={profile=>command('risk_profile',{profile})}/></details>}
    {active&&<ExecutionStatus data={data}/>}
    <UniversePanel data={data} compact busy={busy} onRefresh={()=>call('/universe-refresh')} onBrowse={()=>navigate('markets')}/>
    <div className="simple-work-grid"><div>{chartCard()}</div><section className="panel simple-reasons"><SectionHead title="Botun son kararları" meta="Kayıtlı analizin kısa özeti"/>{reasons.length?reasons.map((d,i)=><div className="simple-reason" key={d.venue+d.symbol+d.market+d.strategy+i}><div><strong>{d.symbol.replace('USDT','')}</strong><span>{d.venue} · {d.market==='spot'?'Spot':'Vadeli'} · {d.strategy==='intraday'?'15dk':'4s'}</span></div><p>{d.message||'Uygun giriş koşulları değerlendiriliyor.'}</p><small className={data.timestamp-d.observed>90?'negative-text':'muted'}>{Math.max(0,Math.floor(data.timestamp-d.observed))} sn önce · {d.selected_method?methodName(d.selected_method):'Giriş bekleniyor'}</small></div>):<div className="simple-wait"><LoaderCircle size={16} className="spin"/><p>İlk analizler hazırlanıyor. Uygun sinyal oluştuğunda gerekçesi burada görünecek.</p></div>}<button className="text-button" onClick={()=>changePresentation('pro')}>Pro görünümde tüm analizler <ArrowRight size={13}/></button></section></div>
    <section className="panel positions-panel"><SectionHead title="Açık pozisyonların" meta="Tüm coinler ve borsalar · güncel sanal hesap" action={<button className="text-button" onClick={()=>navigate('trades')}>İşlem geçmişi <ArrowRight size={13}/></button>}/>{positionTable(data.positions)}</section>
    <div className="simple-links"><button className="button secondary" onClick={()=>navigate('news')}><Newspaper size={14}/>Haberler ve AI yorumları</button><button className="button secondary" onClick={()=>navigate('exchanges')}><Link2 size={14}/>Borsa bağlantıları</button><button className="button secondary" onClick={()=>{changePresentation('pro');navigate('lab');}}><FlaskConical size={14}/>Pro test laboratuvarı</button><span>Görünüm değişince bakiyen, işlemlerin ve çalışma modun korunur.</span></div>
  </>}

  function markets(){if(!data)return null;return <><PageTitle eyebrow="PİYASA GÖZLEMİ" title="Piyasalar" text="Aynı varlığı farklı borsa ve piyasalarda incele."/><UniversePanel data={data} busy={busy} onRefresh={()=>call('/universe-refresh')} onSelect={setSymbol} selected={symbol}/>{chartCard(true)}<div className="panel"><SectionHead title="Borsa karşılaştırması" meta="Son fiyatlar; gerçekleşebilir arbitraj getirisi değildir."/><div className="table-scroll"><table><thead><tr><th>Borsa / piyasa</th><th>Varlık</th><th className="num">Alış / satış</th><th className="num">Son fiyat</th><th className="num">24s hacim</th><th>Güncellik</th></tr></thead><tbody>{data.markets.filter(q=>q.symbol===symbol).map(q=><tr key={q.venue+q.market}><td><strong>{q.venue}</strong> <span className="muted">{q.market==='spot'?'Spot':'Vadeli'}</span></td><td>{q.symbol}</td><td className="num">{n(q.bid,priceDigits(q.bid))} / {n(q.ask,priceDigits(q.ask))}</td><td className="num">{n(q.price,priceDigits(q.price))}</td><td className="num">{n(q.volume/1e6,1)} mn</td><td><Badge tone={Date.now()/1000-q.observed<30?'positive':'warning'}>{mode==='DEMO'?'Demo':Date.now()/1000-q.observed<30?'Güncel':'Eski veri'}</Badge></td></tr>)}</tbody></table></div>{!data.markets.length&&<Empty title="Veri bağlantısı bekleniyor" text="İnternet veya borsa erişimi kontrol edilirken sentetik veriye geçilmez."/>}</div></>}

  function trades(){if(!data)return null;return <><PageTitle eyebrow="EMİR & MUHASEBE" title="İşlemler" text="Her gerçekleşme, her maliyet ve her karar kayıt altında." action={<button className="button danger" onClick={()=>confirm('Tüm sanal pozisyonları kapat','Yeni girişler duracak ve güncel fiyatı bulunan sanal pozisyonlar kapatılacak.',()=>command('close_all'))}><X size={14}/>Tümünü kapat</button>}/><div className="tabs">{[['open','Açık pozisyonlar',data.positions.length],['closed','Kapanan işlemler',data.closed.length],['groups','İşlem grupları',data.groups.length],['audit','Karar günlüğü',data.audit.length]].map(([id,label,count])=><button key={id} onClick={()=>setTradeTab(String(id))} className={tradeTab===id?'selected':''}>{label}<span>{count}</span></button>)}</div><div className="panel">{tradeTab==='open'?positionTable(data.positions):tradeTab==='closed'?positionTable(data.closed,true):tradeTab==='groups'?<>{data.groups.length?data.groups.map(g=><div className="group-card" key={g.id}><div><Badge tone={g.status==='hedged'?'positive':'warning'}>{g.status}</Badge><strong>{g.symbol} · {g.kind==='spot_spot'?'Spot–spot':'Spot–vadeli'}</strong></div><p>{g.note}</p><div className="legs">{Object.entries(g.legs).map(([name,value])=><div key={name}><span>{name==='buy'?'Alış bacağı':'Satış bacağı'}</span><strong>{n((value as Row).filled,5)} BTC</strong><Badge>{(value as Row).status}</Badge></div>)}</div><small>{g.reservation_retained?'Bütçe rezervi korunuyor.':'Senaryo tamamlandı.'}</small></div>):<Empty title="İşlem grubu bulunmuyor" text="Arıza senaryolarını laboratuvarda deneyebilirsiniz. Bu sürümde otomatik gerçek arbitraj emirleri gönderilmez."/>}</>:<div className="audit-list">{data.audit.length?data.audit.map((a,i)=><div key={i}><span className={'audit-dot '+a.kind}/><div><strong>{a.message}</strong><small>{a.kind} · {when(a.time)}</small></div></div>):<Empty title="Henüz karar kaydı yok" text="Motoru başlattığınızda sinyaller ve risk kararları burada görünür."/>}</div>}</div></>}

  function strategies(){if(!data)return null;const cards=data.strategies.filter(s=>strategyFilter==='all'||s.status===strategyFilter);return <><PageTitle eyebrow="STRATEJİ KÜTÜPHANESİ" title="Bir yöntem, açık kurallar." text="Çalıştırılabilir şablonlar ve araştırma yöntemleri birbirinden ayrılır."/><ResearchLibrary data={data}/><h2 className="execution-library-title">İşlem şablonları ve senaryolar</h2><div className="tabs">{[['all','Tümü'],['paper','Sanal seçiciler'],['adaptive','Öğrenilen yöntemler'],['simulation','Grup simülasyonu'],['research','Araştırma']].map(([id,label])=><button className={strategyFilter===id?'selected':''} onClick={()=>setStrategyFilter(id)} key={id}>{label}</button>)}</div><div className="strategy-grid">{cards.map((s,i)=><div className="panel strategy-card" key={s.id}><div className="strategy-top"><span className={'strategy-icon s'+i%3}><TrendingUp size={22}/></span><Badge tone={s.status==='paper'?'positive':s.status==='simulation'?'blue':'neutral'}>{s.status==='paper'?'Sanal seçici':s.status==='adaptive'?'Öğrenen seçicide':s.status==='simulation'?'Senaryo motoru':'Araştırma'}</Badge></div><span className="eyebrow">{s.family}</span><h3>{s.name}</h3><p>{s.description}</p><div className="strategy-detail"><Database size={14}/><span>{s.data}</span></div><div className="strategy-risk"><Shield size={14}/><span>{s.risk}</span></div><div className="strategy-bottom"><span><Clock3 size={13}/>{s.timeframe}</span>{s.status==='paper'?<button className={'toggle '+(s.enabled?'on':'')} role="switch" aria-label={s.name+' etkin'} aria-checked={s.enabled} onClick={()=>command('strategy',{id:s.id,enabled:!s.enabled})}><i/></button>:<span className="locked-label"><LockKeyhole size={12}/>Canlı kilitli</span>}</div></div>)}</div><div className="panel allocation-panel"><SectionHead title="Sınırlı dinamik risk dağıtımı" meta="Onaylı şablon başına en fazla %1 özsermaye riski; portföy toplamı en fazla %2."/>{data.allocation.map(a=><div className="allocation-row" key={a.strategy}><span>{strategyName(a.strategy)}</span><div className="risk-track"><i style={{width:a.share+'%'}}/></div><strong>%{a.share}</strong><small>{a.reason}</small></div>)}</div></>}

  function labPage(){if(!data)return null;return <><PageTitle eyebrow="ARAŞTIRMA ALANI" title="Önce ölç, sonra karar ver." text="Maliyetli geçmiş testler, bağımsız dönem ve model karşılaştırmaları."/><div className="lab-grid"><div className="panel form-panel"><SectionHead title="Yeni deney" meta="İşlem motorunu yavaşlatmadan ayrı süreçte çalışır."/><div className="form-grid"><Field label="Strateji"><select value={lab.strategy} onChange={e=>setLab({...lab,strategy:e.target.value})}><option value="intraday">Gün içi kırılım</option><option value="swing">Swing trend</option></select></Field><Field label="Varlık"><select value={lab.symbol} onChange={e=>setLab({...lab,symbol:e.target.value})}>{data.settings.allowlist.map((s:string)=><option key={s}>{s}</option>)}</select></Field><Field label="Borsa"><select value={lab.venue} onChange={e=>setLab({...lab,venue:e.target.value})}><option>Binance</option><option>Bybit</option></select></Field><Field label="Piyasa"><select value={lab.market} onChange={e=>setLab({...lab,market:e.target.value})}><option value="spot">Spot</option><option value="futures">Vadeli</option></select></Field><Field label="Veri kaynağı"><select value={lab.source} onChange={e=>setLab({...lab,source:e.target.value})}><option value="DEMO">Sentetik Demo</option><option value="PUBLIC">Borsa tarihsel verisi</option></select></Field><Field label="Dönem"><select value={lab.months} onChange={e=>setLab({...lab,months:Number(e.target.value)})}><option value={36}>36 ay</option><option value={24}>24 ay</option><option value={12}>12 ay</option><option value={7}>7 ay · hızlı kontrol</option></select></Field><Field label="Tek taraf komisyon (baz puan)"><input type="number" min="0" max="100" step="0.1" value={lab.fee_bps} onChange={e=>setLab({...lab,fee_bps:Number(e.target.value)})}/></Field><Field label="Tek taraf kayma (baz puan)"><input type="number" min="0" max="100" step="0.1" value={lab.slippage_bps} onChange={e=>setLab({...lab,slippage_bps:Number(e.target.value)})}/></Field></div><div className="form-note"><ShieldCheck size={15}/><span>Son 6 ay bağımsız testtir. Komisyon varsayımları raporda gösterilir; sonuç canlı onayı oluşturmaz.</span></div><div className="button-row"><button disabled={busy||data.jobs.some(j=>j.status==='running')} className="button primary" onClick={()=>call('/jobs',{...lab,kind:'backtest'})}><Play size={14}/>Geçmiş testi çalıştır</button><button disabled={busy||data.jobs.some(j=>j.status==='running')} className="button secondary" onClick={()=>call('/jobs',{...lab,kind:'ml'})}><Sparkles size={14}/>ML ile karşılaştır</button></div></div><div className="panel form-panel"><SectionHead title="Emir grubu arıza testleri" meta="Demo modunda; gerçek emir ve bakiye hareketi yok."/><div className="scenario-list">{[['partial','Kısmi gerçekleşme','Bir bacak tam, diğeri %60 gerçekleşir.'],['unknown','Cevabı kaybolan emir','Bilinmeyen emir bütçesi serbest bırakılmaz.'],['hedged','Eşleşen gerçekleşmeler','İki bacak tamamlanır; grup eşleşir.']].map(([id,title,text])=><button disabled={mode!=='DEMO'} key={id} onClick={()=>command('scenario',{scenario:id})}><span className="scenario-icon"><Activity size={18}/></span><div><strong>{title}</strong><small>{text}</small></div><ChevronRight size={16}/></button>)}</div><button className="text-button" onClick={()=>command('clear_scenarios')}>Demo senaryolarını temizle</button><div className="form-note"><LockKeyhole size={15}/><span>Arbitrajın canlı emir adaptörü bu sürümde kapalıdır. Senaryo sonuçları işlemler ekranında görünür.</span></div></div></div>
    {data.jobs.length>0&&<div className="panel"><SectionHead title="Çalışma kuyruğu"/>{data.jobs.slice(0,4).map(j=><div className="job-row" key={j.id}>{j.status==='running'?<LoaderCircle size={18} className="spin"/>:j.status==='done'?<CheckCircle2 size={18}/>:<TriangleAlert size={18}/>}<div><strong>{j.kind==='ml'?'Model karşılaştırması':'Geçmiş test'}</strong><small>{j.message}</small></div><Badge tone={j.status==='done'?'positive':j.status==='error'?'negative':'blue'}>{j.status==='running'?'Çalışıyor':j.status==='done'?'Tamamlandı':'Tamamlanamadı'}</Badge></div>)}</div>}
    <div className="panel"><SectionHead title="Araştırma raporları" meta="Sentetik veri sonuçları gerçek performans değildir."/>{data.reports.length?<div className="report-list">{data.reports.map(r=><button key={r.id} onClick={async()=>{try{setSelectedReport(await window.terminal.request('/report/'+r.id));}catch{notify('Rapor açılamadı.',false);}}}><span className="strategy-icon"><FlaskConical size={18}/></span><div><strong>{strategyName(r.strategy)} · {r.symbol}</strong><small>{r.kind==='ml'?'ML filtresi karşılaştırması':`${r.venue} · ${r.months} ay · ${r.summary?.count} işlem`}</small></div>{r.needs_retest&&<Badge tone="warning">Yeniden test edilmeli</Badge>}<Badge tone={r.source==='DEMO'?'warning':'blue'}>{r.source==='DEMO'?'Sentetik Demo':'Tarihsel veri'}</Badge><strong className={(r.summary?.net??r.filtered_net)>=0?'positive-text':'negative-text'}>{signed(r.summary?.net??r.filtered_net)} USDT</strong><ChevronRight size={16}/></button>)}</div>:<Empty title="İlk araştırmanı başlat" text="Test sonuçları, maliyetler ve bağımsız dönem metrikleri burada saklanacak." icon={FlaskConical}/>}</div>
    {selectedReport&&<div className="panel report-detail"><SectionHead title="Rapor ayrıntıları" action={<button className="icon-button" title="Raporu kapat" onClick={()=>setSelectedReport(null)}><X size={17}/></button>}/>{selectedReport.needs_retest&&<div className="notice amber"><TriangleAlert size={16}/>Bu rapor önceki gerçekleşme kurallarıyla hesaplandı. Giriş mumundaki stop/ hedef düzeltmesi sonrası aynı testi yeniden çalıştırın; eski net sonuç doğrulanmış sayılmaz.</div>}{selectedReport.source==='DEMO'&&<div className="notice amber"><TriangleAlert size={16}/>Sentetik veri — gerçek performans veya canlıya geçiş kanıtı değildir.</div>}{selectedReport.kind==='ml'?<div className="report-metrics">{[['Temel test neti',selectedReport.baseline_net],['ML filtreli test neti',selectedReport.filtered_net],['Seçilen işlemler',selectedReport.selected_count],['Doğrulama eşiği',selectedReport.threshold]].map(([label,value])=><div key={label}><small>{label}</small><strong>{n(Number(value))}</strong></div>)}</div>:<><div className="report-metrics">{[['Toplam net',selectedReport.summary.net],['Bağımsız test neti',selectedReport.holdout.net],['Bağımsız işlem',selectedReport.holdout.count],['Azami düşüş (%)',selectedReport.max_drawdown],['Komisyon',selectedReport.summary.fees],['Fonlama',selectedReport.summary.funding]].map(([label,value])=><div key={label}><small>{label}</small><strong>{n(Number(value))}</strong></div>)}</div><div className="report-equity"><EquityChart points={selectedReport.curve}/></div></>}{(selectedReport.warnings||[selectedReport.warning]).filter(Boolean).map((w:string,i:number)=><p className="report-warning" key={i}><TriangleAlert size={13}/>{w}</p>)}</div>}
    <div className="panel form-panel"><SectionHead title="AI araştırmacısı" meta="Yalnız mevcut şablonlar için deney adayı önerir; emir yetkisi yoktur." action={<Badge tone={data.settings.ai_enabled?'blue':'neutral'}>{data.settings.ai_enabled?'Yapılandırıldı':'Kapalı'}</Badge>}/><div className="ai-prompt"><input aria-label="Araştırma isteği" placeholder="Örn. BTC swing stratejisinde maliyet duyarlılığını karşılaştır…" value={prompt} onChange={e=>setPrompt(e.target.value)}/><button disabled={busy} className="button secondary" onClick={async()=>{const r=await call('/research-proposal',{prompt});if(r?.proposal)setProposal(r.proposal);}}><Sparkles size={14}/>Aday öner</button></div>{proposal&&<div className="proposal"><strong>{proposal.symbol} · {strategyName(proposal.strategy)}</strong><p>{proposal.hypothesis}</p><p>{proposal.test_plan}</p><Badge>Araştırma adayı · canlıya alınmadı</Badge></div>}</div>
    </>}

  function newsPage(){if(!data)return null;return <><PageTitle eyebrow="DÜNYA & PİYASA" title="Olayların arkasındaki bağlam." text="Kaynak, ilk görülme zamanı ve bot davranışı birlikte izlenir." action={<button disabled={busy} className="button secondary" onClick={()=>call('/news-refresh')}><RefreshCw size={14}/>Kaynakları yenile</button>}/><div className="notice"><ShieldCheck size={17}/><span>Haber katmanı yeni girişleri kısıtlayabilir. Açık pozisyonların çıkışı strateji ve risk motoruna aittir.</span></div><div className="source-grid">{(data.news_sources.length?data.news_sources.map(s=>s.name):['Federal Reserve','SEC','BLS takvimi']).map(name=>{const source=data.news_sources.find(s=>s.name===name);return <div className="panel source-card" key={name}><Globe2 size={19}/><strong>{name}</strong><Badge tone={source?.status==='ok'?'positive':'warning'}>{source?.status==='ok'?'Erişilebilir':source?'Erişilemiyor':'Kontrol ediliyor'}</Badge><small>{source?`${source.count} kayıt · ${when(source.observed)}`:'İlk kaynak kontrolü bekleniyor.'}</small></div>})}</div><div className="news-grid">{data.news.length?data.news.map(event=><div className="panel news-card" key={event.id}><div className="news-meta"><span>{event.source}</span><Badge tone={event.demo?'warning':event.severity==='critical'?'negative':'blue'}>{event.demo?'Demo':event.severity==='scheduled'?'Takvim':event.verification==='official'?'Resmî kaynak':'Doğrulama bekliyor'}</Badge></div><h3>{event.title}</h3><p>{event.action}</p><div className="news-assets">{event.assets.map((a:string)=><Badge key={a}>{a}</Badge>)}</div><div className="news-times"><span>Yayın: {event.published_at?new Date(event.published_at).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'}):'Belirtilmedi'}</span><span>İlk görülme: {new Date(event.first_seen_at).toLocaleString('tr-TR',{timeZone:'Europe/Istanbul'})}</span></div><div className="news-bottom">{event.url?<button className="text-button" onClick={()=>window.terminal.openExternal(event.url).catch(()=>notify('Kaynak bağlantısı izin listesinde değil.',false))}>Kaynağı aç <ExternalLink size={13}/></button>:<span className="muted text-xs">Gerçek haber değildir.</span>}{!event.demo&&<button className="button subtle small-button" onClick={()=>command('news_restrict',{id:event.id,enabled:!(event.restriction_until>Date.now()/1000)})}>{event.restriction_until>Date.now()/1000?'Kısıtı kaldır':'30dk giriş kısıtı'}</button>}</div></div>):<div className="panel wide"><Empty title="Henüz olay alınmadı" text="Resmî kaynaklar kontrol ediliyor. Kaynak erişimi başarısızsa bu durum yukarıda gösterilir." icon={Newspaper}/></div>}</div></>}

  function exchanges(){if(!data)return null;return <><PageTitle eyebrow="BAĞLANTI MERKEZİ" title="İki borsa, tek portföy." text="Anahtarlar Windows korumalı depolamasında tutulur."/><div className="exchange-grid">{data.connections.map(c=><div className="panel exchange-card" key={c.venue}><div className="exchange-logo"><span className={c.venue==='Binance'?'binance-logo':'bybit-logo'}>{c.venue==='Binance'?'◇':'BY'}</span><div><h3>{c.venue}</h3><small>Spot · USDT vadeli</small></div><Badge tone={c.status==='connected'?'positive':c.status==='error'?'negative':'neutral'}>{c.status==='connected'?'Bağlantı doğrulandı':c.status==='stored'?'Anahtar kayıtlı':c.status==='error'?'Bağlantı hatası':'Bağlı değil'}</Badge></div><div className="exchange-info"><span>Hesap doğrulaması</span><strong>{c.authenticated?'Doğrulandı':'Yapılmadı'}</strong><span>Gerçek emir gönderimi</span><strong className="muted">Kilitli</strong><span>Anahtar ortamı</span><strong>{c.testnet?'Borsa test ortamı':'Üretim / halka açık'}</strong></div><button className="button secondary full" disabled={busy} onClick={()=>call('/connect',{venue:c.venue})}><Link2 size={14}/>Bağlantıyı kontrol et</button></div>)}</div><div className="lab-grid"><div className="panel form-panel"><SectionHead title="Korumalı API anahtarı" meta="İlk sürümde hesap okuma ve bağlantı doğrulama için kullanılır."/><div className="form-grid"><Field label="Borsa"><select value={credential.venue} onChange={e=>setCredential({...credential,venue:e.target.value})}><option>Binance</option><option>Bybit</option></select></Field><Field label="Anahtar ortamı"><select value={String(credential.testnet)} onChange={e=>setCredential({...credential,testnet:e.target.value==='true'})}><option value="false">Üretim hesabı</option><option value="true">Borsa test hesabı</option></select></Field><Field label="API anahtarı"><input type="password" autoComplete="off" value={credential.key} onChange={e=>setCredential({...credential,key:e.target.value})}/></Field><Field label="API gizli anahtarı"><input type="password" autoComplete="off" value={credential.secret} onChange={e=>setCredential({...credential,secret:e.target.value})}/></Field></div><button className="button primary" disabled={busy||credential.key.length<8||credential.secret.length<8} onClick={async()=>{setBusy(true);try{const r=await window.terminal.saveCredential(credential);setCredential({...credential,key:'',secret:''});notify(r.message);await refresh();}catch(e){notify(e instanceof Error?e.message:'Anahtar kaydedilemedi.',false);}finally{setBusy(false);}}}><LockKeyhole size={14}/>Şifreleyerek kaydet</button><div className="form-note"><ShieldCheck size={15}/><span>Para çekme izni gerekmez. Anahtar kaydetmek canlı işlem kilidini açmaz.</span></div></div><div className="panel form-panel"><SectionHead title="Canlıya hazırlık" action={<Badge><LockKeyhole size={11}/>Kilitli</Badge>}/><div className="gate-list">{data.live_gate.checks.map((c:Row)=><div key={c.name}>{c.ok?<CheckCircle2 size={17}/>:<LockKeyhole size={16}/>}<span>{c.name}</span></div>)}</div><p className="muted text-xs">{data.live_gate.reason}</p></div></div></>}

  function settingsPage(){if(!data||!settings)return null;const manualList=settings.allowlist.filter((s:string)=>s.trim());const manualInvalid=!settings.auto_universe&&(!manualList.length||new Set(manualList).size>60||manualList.some((s:string)=>!/^([A-Z0-9]{1,16})USDT$/.test(s)));const update=(key:string,value:unknown)=>setSettings({...settings,[key]:value,...(['trade_risk','total_risk','daily_loss','drawdown','leverage','max_positions','symbol_risk','correlated_risk'].includes(key)?{risk_profile:'custom'}:{})});return <><PageTitle eyebrow="ÇALIŞMA ALANI AYARLARI" title="Kontrol sende." text="Risk sınırları birleşik portföye uygulanır; AI bu sınırları değiştiremez." action={<button className="button primary" disabled={busy||manualInvalid} onClick={()=>call('/settings',{...settings,allowlist:settings.auto_universe?data.settings.allowlist:manualList})}><Check size={15}/>Ayarları kaydet</button>}/><div className="panel form-panel"><SectionHead title="Ücretsiz yerel AI" meta="Qwen3 4B · haber analisti ve sınırlı strateji araştırmacısı"/><div className="form-grid">{[['local_ai_enabled','Yerel AI etkin'],['local_ai_news_controls','Güncel haber yorumları yeni giriş riskini etkilesin'],['local_ai_research','Otomatik sınırlı strateji deneyleri']].map(([key,label])=><label className="local-ai-check" key={key}><input type="checkbox" checked={!!settings[key]} onChange={e=>update(key,e.target.checked)}/><span>{label}</span></label>)}</div><p className="muted text-xs">Model bu bilgisayarda çalışır. Durdurulduğunda temel risk/pozisyon yönetimi devam eder. Haber etkisi yalnız güncel resmî kaynağa bağlı ve süreli olabilir. Dil modeli ağırlıkları otomatik değiştirilmez.</p></div><div className="lab-grid"><div className="panel form-panel"><SectionHead title="Risk profili" meta="Seçili profil yeni girişlerde uygulanır; sayısal değişiklikler özel profil oluşturur."/><div className="form-grid">{[['trade_risk','İşlem / grup riski (%)',0.75],['total_risk','Toplam açık risk (%)',4],['daily_loss','Günlük kayıp eşiği (%)',3],['drawdown','Hesap düşüşü eşiği (%)',15],['leverage','Azami kaldıraç',5],['max_positions','Azami pozisyon / grup',12],['symbol_risk','Tek coin riski (%)',1.5],['correlated_risk','Bağlantılı coin riski (%)',2.5],['paper_balance','Sanal başlangıç bakiyesi',10000000]].map(([key,label,max])=><Field key={key} label={String(label)}><input type="number" step={key==='leverage'||key==='max_positions'?'1':'0.1'} min="0.1" max={max} value={settings[String(key)]} onChange={e=>update(String(key),Number(e.target.value))}/></Field>)}<Field label="Yeni sanal işlemlerin çıkış politikası"><select aria-label="Çıkış politikası" value={settings.exit_policy||"adaptive"} onChange={e=>update("exit_policy",e.target.value)}><option value="adaptive">Kısmi kâr + başabaş + takip stopu</option><option value="fixed">Sabit stop ve hedef</option></select></Field></div><p className="muted text-xs">Çıkış politikası yalnız yeni pozisyonlara uygulanır. Yeni başlangıç bakiyesi, sanal hesap sıfırlandığında uygulanır. Limitler gerçekleşen kayıp için garanti değildir.</p></div><div className="panel form-panel"><SectionHead title="Piyasa tarama kapsamı" meta="Otomatik keşif veya sana özel sınırlı havuz."/><label className="local-ai-check"><input aria-label="Otomatik coin keşfi" type="checkbox" checked={!!settings.auto_universe} onChange={e=>setSettings({...settings,auto_universe:e.target.checked,...(!e.target.checked&&settings.allowlist.length>60?{allowlist:[...new Set([...data.positions.map(p=>p.symbol),...settings.allowlist])].slice(0,60)}:{})})}/><span>Borsalardaki USDT coinlerini otomatik keşfet</span></label>{settings.auto_universe?<div className="form-note"><Globe2 size={15}/><span>Binance ve Bybit listeleri güncellenir; geniş havuzun fiyat/likidite taraması ile sırayla derin analizi ayrı yürür. Tüm coinler aynı anda eğitime alınmaz. Bu değişiklik bakiye veya işlem sınırını artırmaz.</span></div>:<><Field label="Manuel USDT pariteleri · her satıra bir coin"><textarea className="universe-manual-input" aria-label="Manuel coin listesi" value={settings.allowlist.join('\n')} onChange={e=>update('allowlist',e.target.value.toUpperCase().split(/[\n,]/).map(s=>s.trim()))}/></Field><p className="universe-manual-count">{new Set(manualList).size} / 60 coin · Otomatikten geçişte ilk 60 coin ve açık pozisyonların coinleri korunur; kaydetmeden önce düzenleyebilirsin.{manualInvalid&&<strong className="negative-text"> Geçerli biçimde 1–60 USDT paritesi yaz.</strong>}</p></>}<div className="form-note"><Shield size={15}/><span>Her yeni girişte desteklenen ürün, güncel fiyat, likidite, spread ve birleşik risk kontrolleri uygulanır. Açık pozisyonun coinini listeden çıkarmadan önce pozisyonu kapatmalısın.</span></div><SectionHead title="Yerel kayıtlar"/><div className="settings-actions"><button className="button secondary" onClick={()=>command('backup')}><Database size={14}/>Veritabanını yedekle</button><button className="button subtle" onClick={()=>confirm('Sanal hesabı sıfırla','Açık pozisyon yoksa yeni sanal hesap oluşturulacak. Eski denetim kayıtları korunur.',()=>command('reset'))}><RefreshCw size={14}/>Sanal hesabı sıfırla</button></div></div></div><div className="lab-grid"><div className="panel form-panel"><SectionHead title="Telegram bildirimleri" action={<button role="switch" aria-label="Telegram etkin" aria-checked={settings.telegram_enabled} className={'toggle '+(settings.telegram_enabled?'on':'')} onClick={()=>update('telegram_enabled',!settings.telegram_enabled)}><i/></button>}/><Field label="Sohbet kimliği"><input value={settings.telegram_chat_id} onChange={e=>update('telegram_chat_id',e.target.value)}/></Field><Field label="Bot tokeni (korumalı)"><input type="password" value={secret.telegram} autoComplete="off" onChange={e=>setSecret({...secret,telegram:e.target.value})}/></Field><div className="button-row"><button className="button secondary" onClick={async()=>{try{await window.terminal.saveSecret('telegram',secret.telegram);setSecret({...secret,telegram:''});notify('Telegram tokeni korumalı depoya kaydedildi.');}catch{notify('Token kaydedilemedi.',false);}}}>Tokeni kaydet</button><button className="button subtle" onClick={()=>call('/telegram-test')}>Test bildirimi</button></div><p className="muted text-xs">Kritik olaylar anında; günlük haber özeti İstanbul saatiyle 21.00 sonrasında gönderilir.</p></div><div className="panel form-panel"><SectionHead title="İsteğe bağlı AI araştırmacısı" action={<button role="switch" aria-label="AI etkin" aria-checked={settings.ai_enabled} className={'toggle '+(settings.ai_enabled?'on':'')} onClick={()=>update('ai_enabled',!settings.ai_enabled)}><i/></button>}/><div className="form-grid"><Field label="Model kimliği"><input value={settings.ai_model} placeholder="Hesabınızda erişilebilir model" onChange={e=>update('ai_model',e.target.value)}/></Field><Field label="API anahtarı (korumalı)"><input type="password" autoComplete="off" value={secret.ai} onChange={e=>setSecret({...secret,ai:e.target.value})}/></Field>{[['ai_daily_budget','Günlük bütçe (USD)'],['ai_monthly_budget','Aylık bütçe (USD)'],['ai_input_price','1 milyon giriş tokeni fiyatı (USD)'],['ai_output_price','1 milyon çıkış tokeni fiyatı (USD)']].map(([key,label])=><Field label={label} key={key}><input type="number" min="0" step="0.01" value={settings[key]} onChange={e=>update(key,Number(e.target.value))}/></Field>)}</div><button className="button secondary" onClick={async()=>{try{await window.terminal.saveSecret('ai',secret.ai);setSecret({...secret,ai:''});notify('AI anahtarı korumalı depoya kaydedildi.');}catch{notify('Anahtar kaydedilemedi.',false);}}}>AI anahtarını kaydet</button><p className="muted text-xs">Güncel token fiyatını sağlayıcıdan doğrulayın. Yerel bütçe rezervi girilen fiyatlara dayanır; sağlayıcı harcama limiti ayrıca yapılandırılmalıdır.</p></div></div><div className="panel about-panel"><div className="brand-mark"><Activity size={23}/></div><div><strong>Kripto Terminali <span className="muted">v{data.version}</span></strong><p>Yerel araştırma ve sanal işlem sürümü. Gerçek emir gönderimi kapalıdır.</p><button className="text-button" onClick={()=>window.terminal.openExternal('https://www.tradingview.com/')}>Grafikler: TradingView Lightweight Charts <ExternalLink size={12}/></button></div><button className="button danger" onClick={()=>confirm('Motoru durdur ve çık','Sanal motor duracak ve uygulama kapanacak. Yerel simülasyon bilgisayar kapalıyken çalışmaz.',()=>window.terminal.windowAction('quit'))}><Power size={14}/>Uygulamadan çık</button></div></>}

  return <div className={"app-shell presentation-"+presentation} data-testid="app-shell"><div className="titlebar"><div className="titlebar-name"><Activity size={13}/>KRİPTO TERMİNALİ<span>Çalışma alanı</span></div><div className="window-controls"><button aria-label="Küçült" onClick={()=>window.terminal.windowAction('minimize')}><Minus size={14}/></button><button aria-label="Büyüt" onClick={()=>window.terminal.windowAction('maximize')}><Maximize2 size={12}/></button><button aria-label="Sistem tepsisine küçült" onClick={()=>window.terminal.windowAction('close')}><X size={15}/></button></div></div><div className="app-body"><aside className="sidebar"><div className="brand"><div className="brand-mark"><Activity size={26}/></div><div><strong>kripto<span>terminali</span></strong><small>PİYASANIN ÖTESİNE BAK.</small></div></div><div className="workspace-label">ÇALIŞMA ALANI</div><nav aria-label="Ana gezinme">{nav.filter(item=>!simple||['overview','chat','operations','markets','trades','strategies','settings'].includes(item.id)).map(item=><button key={item.id} className={page===item.id?'selected':''} onClick={()=>navigate(item.id)}><item.icon size={18}/><span>{item.label}</span>{item.id==='news'&&<i className="nav-dot"/>}{item.id==='lab'&&<Badge>LAB</Badge>}</button>)}</nav><div className="sidebar-bottom">{simple&&<button className="pro-entry button secondary" onClick={()=>changePresentation('pro')}><SlidersHorizontal size={15}/>Pro araçlarını aç</button>}<div className="sidebar-risk"><span><ShieldCheck size={15}/>Önce risk kontrolü</span><p>Her sinyal, ortak portföy sınırlarından geçer.</p><div><span className="status-dot"/>Canlı işlem kilitli</div></div><button className="profile" onClick={()=>navigate('settings')}><span className="avatar">KT</span><div><strong>Kişisel çalışma alanı</strong><small>Yerel cihaz · v{data?.version||'…'}</small></div><Settings2 size={14}/></button></div></aside><div className="workspace"><header className="topbar"><div className="breadcrumb">Çalışma alanı<ChevronRight size={13}/><strong>{nav.find(i=>i.id===page)?.label}</strong></div><form className="search" onSubmit={e=>{e.preventDefault();const match=data?.settings.allowlist.find((s:string)=>s.includes(search.toUpperCase()));if(match)selectCoin(match);else notify('Varlık izin listesinde bulunamadı.',false);}}><Search size={15}/><input aria-label="Varlık ara" placeholder="Varlık ara…" value={search} onChange={e=>setSearch(e.target.value)}/><kbd>↵</kbd></form><div className="topbar-actions"><div className="presentation-toggle" role="group" aria-label="Arayüz görünümü" title="Yalnız görünümü değiştirir; işlem modu ve hesap korunur.">{[['simple','Sade'],['pro','Pro']].map(([id,label])=><button key={id} aria-pressed={presentation===id} onClick={()=>changePresentation(id as 'simple'|'pro')}>{label}</button>)}</div><span className={'engine-status '+(entryGate?.blocked?'blocked':data?.running?'running':'')} title={entryGate?.blocked?entryGate.message:undefined}><i className="status-dot"/>{engineLabel}</span><div className="mode-select"><span className="mode-dot"/><select aria-label="Çalışma modu" value={mode||'PAPER'} onChange={e=>command('mode',{mode:e.target.value})}><option value="DEMO">Demo</option><option value="PAPER">Sanal</option><option value="TEST">Borsa test · kilitli</option><option value="LIVE">Canlı · kilitli</option></select></div><button className="icon-button notification-button" title="Haber merkezini aç" onClick={()=>navigate('news')}><Bell size={17}/><i/></button><span className="avatar small">KT</span></div></header>
    <main className="content"><div className={'mode-banner '+(mode==='PAPER'?'paper':'')}><span><FlaskConical size={15}/><strong>{mode==='PAPER'?'SANAL İŞLEM':'DEMO ÇALIŞMA ALANI'}</strong><span>{mode==='PAPER'?'Gerçek piyasa verileri · sanal bakiye ve emirler · maliyetler tahminidir.':'Örnek veriler ve sentetik performans · gerçek para veya emir kullanılmaz.'}</span></span><button disabled={!data||busy} className={'button small-button '+(data?.running?'secondary':'primary')} onClick={()=>command(data?.running?'pause':'start')}>{data?.running?<Pause size={12}/>:<Play size={12}/>} {data?.running?'Yeni girişleri durdur':'Sanal motoru başlat'}</button></div>
    {error&&<div className="notice amber"><TriangleAlert size={17}/>{error}<button className="text-button" onClick={refresh}>Yeniden dene</button></div>}{data?.halt&&<div className="notice red"><Shield size={17}/>{data.halt}</div>}
    {!data?<div className="startup"><span className="brand-mark"><Activity size={35}/></span><h1>Çalışma alanın hazırlanıyor.</h1><p>Yerel işlem motoru ve güvenli kayıtlar başlatılıyor.</p><LoaderCircle className="spin"/></div>:page==='overview'?(simple?simpleOverview():overview()):page==='chat'?<ChatPanel data={data} openSettings={()=>navigate('settings')}/>:page==='operations'?<OperationsPanel data={data} simple={simple} notify={notify} openChat={()=>navigate('chat')}/>:page==='markets'?markets():page==='trades'?trades():page==='strategies'?strategies():page==='lab'?labPage():page==='news'?newsPage():page==='exchanges'?exchanges():settingsPage()}
    </main><footer className="statusbar"><span><span className="status-dot"/>{data?'Yerel motor bağlı':'Yerel motor bekleniyor'}</span><span>{mode==='DEMO'?'Demo verisi':data?.source_status==='ok'?'Piyasa verisi güncel':data?.source_status==='partial'?'Bazı veri bağlantıları eksik':'Veri bağlantısı bekleniyor'}</span><span className="statusbar-right">{new Date().toLocaleTimeString('tr-TR',{timeZone:'Europe/Istanbul'})} UTC+3 <span>•</span> v{data?.version||'…'}</span></footer></div></div>
    {mode==='DEMO'&&data&&<button className="demo-action" title="Seçili piyasada risk kontrolünden geçen örnek sanal pozisyon oluştur" onClick={()=>command('demo_signal',{symbol,venue,market})}><Plus size={14}/>Demo işlemi</button>}
    {toast&&<div className={'toast '+(toast.ok?'success':'error')} role="status">{toast.ok?<CheckCircle2 size={18}/>:<TriangleAlert size={18}/>}<span>{toast.text}</span><button className="icon-button" aria-label="Bildirimi kapat" onClick={()=>setToast(null)}><X size={14}/></button></div>}
    {confirmation&&<div className="modal-backdrop"><div className="modal" role="dialog" aria-modal="true"><span className="modal-icon"><Shield size={27}/></span><h2>{confirmation.title}</h2><p>{confirmation.text}</p><div className="button-row"><button className="button secondary" onClick={()=>setConfirmation(null)}>Vazgeç</button><button className="button primary" onClick={()=>{confirmation.run();setConfirmation(null);}}>Onayla</button></div></div></div>}
  </div>;
}

function PageTitle({eyebrow,title,text,action}:{eyebrow:string;title:string;text:string;action?:React.ReactNode}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{text}</p></div>{action}</div>}
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}

